63|export function parseGateSemver(input) {
64|	if (typeof input !== "string") return null;
65|	const m = input.trim().replace(/^v/, "").match(/^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/);
66|	if (!m) return null;
67|	return {
68|		major: Number(m[1]),
69|		minor: Number(m[2]),
70|		patch: Number(m[3]),
71|		prerelease: m[4] ? m[4].split(".") : [],
72|	};
