300|/***
301| * MARK: discoveryStatusSummary
302| * @description Summarizes the Runner's per-harness auto-detect status
303| *   (`capabilities.discoveryStatus`, falling back to the raw facts copy)
304| *   for the Models block: stable per-harness counts plus the first leg
305| *   warning. Null when the Runner/backend predates discovery status, so
306| *   old records render exactly as before.
307| * @example discoveryStatusSummary({ capabilities: { discoveryStatus: { pi: { ok: true, count: 2 } } } }) => { counts: 'pi:2', warning: null }
308| * @param {Object} [runner={}] - Runner record.
309| * @returns {{counts: string, warning: string|null}|null} Summary, or null when unknown.
310| ***/
311|export const discoveryStatusSummary = (runner = {}) => {
312|  const status = runner?.capabilities?.discoveryStatus ?? runner?.facts?.discoveryStatus;
313|  if (!status || typeof status !== 'object' || Array.isArray(status)) return null;
314|  const ids = Object.keys(status).sort();
315|  if (ids.length === 0) return null;
316|  const counts = ids
317|    .map((id) => {
318|      const slice = status[id];
319|      const rawCount = slice && typeof slice.count === 'number' ? slice.count : 0;
320|      const count = Number.isFinite(rawCount) && rawCount >= 0 ? Math.floor(rawCount) : 0;
321|      return `${id}:${count}`;
322|    })
323|    .join(', ');
324|  const warned = ids.find((id) => {
325|    const slice = status[id];
326|    return Boolean(slice && typeof slice === 'object' && (slice.ok === false || (slice.error && typeof slice.error === 'object')));
327|  });
328|  let warning = null;
329|  if (warned) {
330|    const err = status[warned]?.error;
331|    const code = err && typeof err.code === 'string' && err.code ? err.code : 'discovery failed';
332|    const msg = err && typeof err.message === 'string' && err.message ? err.message.slice(0, 200) : '';
333|    warning = msg ? `${warned}: ${code} — ${msg}` : `${warned}: ${code}`;
334|  }
335|  return { counts, warning };
336|};
