340| * @description Summarizes WHERE one Runner's advertised model list comes
341| *   from (`capabilities.modelSource`, falling back to the raw facts copy):
342| *   `pinned` (operator pin only), `pinned+discovered` (pin unioned with
343| *   auto-detected ids — the current runner default), `discovered`
344| *   (auto-detect fills in), or `unpinned` (nothing advertised) — plus the
345| *   newest per-harness scan time across `discoveryStatus` slices. Null
346| *   when the Runner/backend predates both signals, so old records render
347| *   exactly as before.
348| * @example modelSourceSummary({ capabilities: { modelSource: 'pinned' } }) => { source: 'pinned', scannedAtMs: null }
349| * @param {Object} [runner={}] - Runner record.
350| * @returns {{source: string|null, scannedAtMs: number|null}|null} Summary, or null when unknown.
351| ***/
352|export const modelSourceSummary = (runner = {}) => {
353|  const raw = runner?.capabilities?.modelSource ?? runner?.facts?.modelSource;
354|  const source =
355|    raw === 'pinned' || raw === 'pinned+discovered' || raw === 'discovered' || raw === 'unpinned'
356|      ? raw
357|      : null;
358|  const status = runner?.capabilities?.discoveryStatus ?? runner?.facts?.discoveryStatus;
359|  let scannedAtMs = null;
360|  if (status && typeof status === 'object' && !Array.isArray(status)) {
361|    for (const slice of Object.values(status)) {
362|      const at = slice && typeof slice.atMs === 'number' && Number.isFinite(slice.atMs) && slice.atMs >= 0
363|        ? slice.atMs
364|        : null;
365|      if (at !== null && (scannedAtMs === null || at > scannedAtMs)) scannedAtMs = at;
366|    }
367|  }
368|  if (!source && scannedAtMs === null) return null;
369|  return { source, scannedAtMs };
