756|/***
757| * MARK: runnerShasMatch
758| * @description Whether two commit shas name the same commit: exact match
759| *   or either side a prefix of the other (the backend reports a short
760| *   commit while Runners report full shas). Both sides need at least 4
761| *   hex characters — anything shorter reads as unknown, never as a
762| *   match or a mismatch.
763| * @example runnerShasMatch('abc1234def', 'abc1234') => true
764| * @param {string|null} [runnerSha=null] - Runner build sha.
765| * @param {string|null} [backendSha=null] - Backend build commit.
766| * @returns {boolean} True when both are known and name the same commit.
767| ***/
768|const runnerShasMatch = (runnerSha = null, backendSha = null) => {
769|  const a = typeof runnerSha === 'string' ? runnerSha.trim().toLowerCase() : '';
770|  const b = typeof backendSha === 'string' ? backendSha.trim().toLowerCase() : '';
771|  if (a.length < 4 || b.length < 4) return false;
772|  return a === b || a.startsWith(b) || b.startsWith(a);
773|};
774|
775|/***
776| * MARK: runnerBuildWarning
777| * @description Stale-code warning for one Runner record, or null when
778| *   there is nothing to say. Warns when the Runner's own code changed
779| *   after boot, or when its build sha provably differs from the backend
780| *   commit — and stays silent for dev checkouts (build info still
781| *   shows), for unknown builds or backend commits, and for matching
782| *   shas. Advisory only: the caller renders the message and never
783| *   disables anything (warn, never block).
784| * @example runnerBuildWarning({ facts: { versions: { build: { sha: 'aaa' }, codeChangedSinceBoot: true } } }, 'bbb') => { kind: 'code-changed', message: '…' }
785| * @param {Object} [runner={}] - Runner record.
786| * @param {string|null} [backendSha=null] - Backend build commit (`GET /status` → `build.commit`).
787| * @returns {{kind: string, message: string}|null} Warning, or null.
788| ***/
789|export const runnerBuildWarning = (runner = {}, backendSha = null) => {
790|  const versions = runnerVersionsBlock(runner);
791|  if (!versions || typeof versions !== 'object') return null;
792|  const build = describeRunnerBuild(runner);
793|  if (build?.isDev) return null;
794|  // An explicit true is provable staleness on its own: old Runners never
795|  // send the flag at all, so no sha comparison is needed for this branch.
796|  if (versions.codeChangedSinceBoot === true) {
797|    return {
798|      kind: 'code-changed',
799|      message:
800|        "This runner's code changed after it started — restart or update it so it runs the current code.",
801|    };
802|  }
803|  const backend = typeof backendSha === 'string' && backendSha.trim().length >= 4 ? backendSha.trim() : null;
804|  if (!build || !backend) return null;
805|  if (runnerShasMatch(build.sha, backend)) return null;
806|  return {
807|    kind: 'sha-mismatch',
808|    message: `This runner was built from ${build.shortSha} but the backend runs ${backend.slice(0, 7)} — restart or update it so they match.`,
809|  };
810|};

